const KEY='lpp-lehan-film-studio-v01';
const PUTRI_TUJUH_BIBLE={setting:'Negeri Seri Bunga Tanjung, kerajaan Melayu legendaris di kawasan pesisir Dumai, Riau, pada masa lampau. Jangan menetapkan abad atau tahun tertentu jika tidak disebutkan dalam Master Storyline.',visualStyle:'Historical cinematic realism; cinematic 16:9; muted earthy historical cinema dengan palet warna dan color grading konsisten; detail realistis, pencahayaan sinematik yang sesuai waktu dan lokasi adegan.',languageRules:'Narasi menggunakan Bahasa Indonesia baku dengan nuansa Melayu Riau. Dialog karakter menggunakan dialek Melayu Pesisir hanya jika ditentukan storyboard; hindari slang modern. Google Flow menghasilkan visual dan ambience/SFX sesuai instruksi; narasi, dialog, dan musik final ditambahkan terpisah di CapCut sesuai workflow produksi.',continuity:'Master Character Sheet Revisi 02 adalah acuan resmi wajah, busana, aksesori, dan identitas seluruh karakter. Master Storyline menjadi acuan urutan dan kesinambungan cerita. Jangan mengubah identitas wajah, kostum, aksesori, arsitektur, lingkungan, atau color grading tanpa persetujuan produksi. Tampilkan hanya karakter yang ditetapkan tampil dalam klip; karakter narator atau pengisi suara tidak divisualisasikan kecuali storyboard secara eksplisit memerintahkannya.'};
function normalizeBible(p){const b=p.masterBible||{},d=/putri tujuh/i.test(p?.name||'')?PUTRI_TUJUH_BIBLE:{setting:'Setting belum ditentukan dalam Master Bible proyek.',visualStyle:'Cinematic 16:9; ikuti gaya visual proyek yang telah disetujui.',languageRules:'Gunakan bahasa dan aturan dialog yang ditetapkan dalam proyek; jangan menambahkan dialog yang tidak ditentukan.',continuity:'Pertahankan kontinuitas visual dan naratif yang telah disetujui.'};p.masterBible={setting:b.setting?.trim()||d.setting,visualStyle:b.visualStyle?.trim()||d.visualStyle,languageRules:b.languageRules?.trim()||d.languageRules,continuity:b.continuity?.trim()||d.continuity};return p.masterBible}
const isNarrator=c=>/narator|narrator/i.test(c?.name||'')||c?.id==='narator';
const $=s=>document.querySelector(s);
const uid=()=>Math.random().toString(36).slice(2,10);
const starter={projects:[{id:'putri-tujuh',workspaceType:'lpp',generationMode:'hybrid',name:'PUTRI TUJUH',description:'Legenda dari Dumai, Riau — proyek uji produksi LPP.',genre:'Legenda Melayu · Cinematic',createdAt:new Date().toISOString(),characters:[{id:'ratu',name:'Ratu Cik Sima',visual:'Perempuan dewasa; sanggul hitam; mahkota tinggi berhias emas; busana kerajaan marun bermotif emas.',voice:'Gacrux',rules:'Wajah, mahkota, sanggul, warna busana marun dan motif emas harus konsisten.'},{id:'pangeran',name:'Pangeran Empang Kuala',visual:'Busana hijau bersulam; ikat kepala songket; rambut hitam sebahu; kumis dan janggut tipis.',voice:'Alnilam',rules:'Pertahankan wajah, busana hijau, ikat kepala songket, dan rambut sebahu.'},{id:'narator',name:'Narator',visual:'Tidak tampil di layar kecuali ditentukan storyboard.',voice:'Charon',rules:'Suara pria dewasa, rendah, tenang, informatif, dan berwibawa.'}],clips:[]}],activeProjectId:'putri-tujuh'};
let state=load();let editingProject=null,editingCharacter=null,editingClip=null,editingEpisodeId=null,activeView='dashboard',pendingCharacterImage='';
function load(){try{const data=JSON.parse(localStorage.getItem(KEY))||structuredClone(starter);data.projects=(data.projects||[]).map(p=>({...p,workspaceType:p.workspaceType||(/putri tujuh/i.test(p.name||'')?'lpp':'creator'),generationMode:p.generationMode||'hybrid',masterBible:{setting:'',visualStyle:'',languageRules:'',continuity:'',...(p.masterBible||{})},characters:p.characters||[],clips:(p.clips||[]).map(c=>({...c,characterIds:c.characterIds||[],voiceCharacterIds:c.voiceCharacterIds||[]}))}));return data}catch{return structuredClone(starter)}}
function save(nextState=state){try{localStorage.setItem(KEY,JSON.stringify(nextState));return true}catch(err){toast('Penyimpanan perangkat penuh atau tidak tersedia. Data aktif tidak diganti. Unduh backup dan kurangi ukuran gambar referensi bila perlu.');return false}}
function project(){const p=state.projects.find(p=>p.id===state.activeProjectId)||state.projects[0];if(p)normalizeBible(p);return p}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function setView(v){activeView=v;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#crumbTitle').textContent=({dashboard:'Dashboard',projects:'Proyek Film',story:'Pengembangan Cerita',characters:'Master Character',storyboard:'Storyboard & Prompt',engines:'AI Engine'})[v];render();$('#sidebar').classList.remove('open')}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');
function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function render(){const p=project();let html='';if(activeView==='dashboard')html=dashboard(p);if(activeView==='projects')html=projects();if(activeView==='story')html=storyStudio(p);if(activeView==='characters')html=characters(p);if(activeView==='storyboard')html=storyboard(p);if(activeView==='engines')html=engines();$('#app').innerHTML=html;bindDynamic()}
function storageHealth(){const imageCount=state.projects.reduce((n,p)=>n+p.characters.reduce((m,c)=>m+['referenceImage','referenceFront','referenceSide','referenceFullBody'].filter(k=>typeof c[k]==='string'&&c[k]).length,0),0);let size='Tidak tersedia';try{size=(new Blob([localStorage.getItem(KEY)||'']).size/1024/1024).toFixed(2)+' MB'}catch{}return '<div class="panel" style="margin-top:18px"><div class="section-head" style="margin-top:0"><h3>Data & Backup Health</h3><small>Ringkasan lokal perangkat</small></div><div class="stats"><div class="stat"><span>Ukuran data lokal</span><strong>'+size+'</strong></div><div class="stat"><span>Referensi gambar</span><strong>'+imageCount+'</strong></div><div class="stat"><span>Proyek tersimpan</span><strong>'+state.projects.length+'</strong></div></div><p class="small-note">Ukuran ini adalah perkiraan data aplikasi pada localStorage, bukan kapasitas total browser. Backup semua tetap disarankan sebelum impor besar atau perubahan perangkat.</p></div>'}
function dashboard(p){const clips=p?.clips||[],chars=p?.characters||[];return `${head('LPP · PRODUCTION WORKSPACE','Studio produksi sinematik','Ruang kerja terpusat untuk mengembangkan cerita, menjaga kontinuitas karakter, dan menyiapkan produksi film AI.')}<section class="hero"><div><div class="eyebrow">CURRENT PROJECT · ${esc(p?.genre||'FILM PROJECT')}</div><h2>${esc(p?.name||'Belum ada proyek')}</h2><p>${esc(p?.description||'Mulai dengan membuat proyek film pertama Anda.')}</p><button class="btn btn-primary" data-go="storyboard">Buka ruang produksi →</button></div><div class="hero-mark">L</div></section><div class="stats"><div class="stat"><span>Proyek film</span><strong>${state.projects.length}</strong></div><div class="stat"><span>Karakter aktif</span><strong>${chars.length}</strong></div><div class="stat"><span>Klip storyboard</span><strong>${clips.length}</strong></div></div>${storageHealth()}<div class="section-head"><h3>Alur kerja produksi</h3><small>Versi MVP 0.1</small></div><div class="panel"><h3>Master Bible → Storyboard → Prompt → Rendering</h3><p>Susun identitas visual dan aturan karakter terlebih dahulu. Setelah storyboard siap, prompt dapat disalin ke mesin video AI pilihan. Integrasi rendering otomatis akan diaktifkan setelah kredensial provider disiapkan.</p><div class="card-actions"><button class="btn btn-outline" data-go="characters">Kelola karakter</button><button class="btn btn-outline" data-go="engines">Lihat AI engine</button></div></div><div class="section-head"><h3>Proyek terbaru</h3><button class="btn btn-outline btn-small" data-go="projects">Semua proyek</button></div>${state.projects.slice(0,3).map(projectCard).join('')||empty('Belum ada proyek','Buat proyek film pertama untuk memulai.')}`}
function projectCard(p){return `<article class="project-card"><div class="meta">${p.workspaceType==='lpp'?'LPP STUDIO':'CREATOR STUDIO'} · ${p.generationMode==='hybrid'?'MANUAL + API-READY':'MANUAL FLOW'}</div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.genre||'FILM PROJECT')}</div><p>${esc(p.description||'Belum ada deskripsi.')}</p><div class="meta">${p.characters.length} KARAKTER · ${p.clips.length} KLIP</div><div class="card-actions"><button class="btn btn-primary btn-small" data-open-project="${p.id}">Buka proyek</button><button class="btn btn-outline btn-small" data-edit-project="${p.id}">Ubah</button><button class="btn btn-outline btn-small danger" data-delete-project="${p.id}">Hapus</button></div></article>`}
function projects(){return `${head('WORKSPACE','Proyek film','Setiap film memiliki Master Bible, karakter, storyboard, dan arsip produksi.',`<button class="btn btn-primary" id="newProject">＋ Proyek baru</button>`)}<div class="project-grid">${state.projects.map(projectCard).join('')||empty('Belum ada proyek','Tekan Proyek baru untuk membuat ruang kerja.')}</div>`}
function getProjectEpisodes(p){
 if(!Array.isArray(p.episodes)){
  const d=p.storyDevelopment||{},byNumber=new Map();
  (p.clips||[]).forEach(c=>{const n=Math.max(1,Number(c.episodeNumber)||1);if(!byNumber.has(n))byNumber.set(n,{id:'episode-'+n,number:n,title:c.episodeTitle||('Episode '+n),synopsis:'',masterStoryline:'',outline:'',status:'planning',notes:''});});
  if(!byNumber.has(1))byNumber.set(1,{id:'episode-1',number:1,title:'Episode 1',synopsis:'',masterStoryline:'',outline:'',status:'planning',notes:''});
  const first=byNumber.get(1);
  if(d.episodeNumber&&d.episodeTitle&&d.episodeNumber!==1&&!byNumber.has(Number(d.episodeNumber)))byNumber.set(Number(d.episodeNumber),{id:'episode-'+d.episodeNumber,number:Number(d.episodeNumber),title:d.episodeTitle,synopsis:'',masterStoryline:'',outline:'',status:'planning',notes:''});
  const active=byNumber.get(Number(d.episodeNumber)||1)||first;
  active.outline=d.episodeOutline||'';
  active.masterStoryline=d.episodeMasterStoryline||'';
  active.synopsis=d.episodeSynopsis||'';
  active.notes=d.episodeNotes||'';
  p.episodes=[...byNumber.values()].sort((x,y)=>x.number-y.number);
  save();
 }
 return p.episodes;
}
function storyStudio(p){
 if(!p)return empty('Pilih proyek','Buat atau pilih proyek terlebih dahulu.');
 const d=p.storyDevelopment||{},episodes=getProjectEpisodes(p);
 if(!episodes.some(x=>x.id===editingEpisodeId))editingEpisodeId=episodes[0]?.id||null;
 const active=episodes.find(x=>x.id===editingEpisodeId)||episodes[0];
 const cards=episodes.map(ep=>{
  const count=(p.clips||[]).filter(c=>(Number(c.episodeNumber)||1)===ep.number).length;
  const statusLabels={planning:'Perencanaan',story_approved:'Cerita disetujui',in_production:'Dalam produksi',completed:'Selesai',archived:'Arsip'};
  return '<article class="episode-card"><div><div class="meta">EPISODE '+String(ep.number).padStart(2,'0')+' · '+(statusLabels[ep.status]||'Perencanaan')+'</div><h3>'+esc(ep.title||('Episode '+ep.number))+'</h3><p>'+esc(ep.synopsis||'Sinopsis episode belum diisi.')+'</p><small>'+count+' klip storyboard</small></div><button class="btn btn-outline btn-small" data-edit-episode="'+esc(ep.id)+'">Kelola episode</button></article>';
 }).join('');
 return `${head('STORY DEVELOPMENT','Master Storyline & Episode Manager · '+esc(p.name),'Kelola cerita induk dan setiap episode dalam satu proyek. Setiap episode mempunyai storyline, outline, status, dan klipnya sendiri.')}
 <div class="panel"><div class="section-head" style="margin-top:0"><h3>Master Storyline proyek</h3><small>Canon cerita lintas episode</small></div>
 <label>Logline<textarea id="storyLogline" rows="2" maxlength="600" placeholder="Inti cerita dalam satu atau dua kalimat.">${esc(d.logline||'')}</textarea></label>
 <label>Sinopsis utama<textarea id="storySynopsis" rows="4" maxlength="5000" placeholder="Gambaran cerita dari awal hingga akhir.">${esc(d.synopsis||'')}</textarea></label>
 <div class="form-grid"><label>Konflik utama<textarea id="storyConflict" rows="3" maxlength="2000">${esc(d.conflict||'')}</textarea></label><label>Tema dan pesan cerita<textarea id="storyThemes" rows="3" maxlength="2000">${esc(d.themes||'')}</textarea></label></div>
 <label>Catatan canon global<textarea id="storyNotes" rows="3" maxlength="3000" placeholder="Fakta dan keputusan cerita yang berlaku lintas episode.">${esc(d.notes||'')}</textarea></label>
 <button class="btn btn-primary" id="saveStoryDevelopment">Simpan Master Storyline</button></div>
 <div class="section-head"><div><h3>Daftar episode</h3><small>${episodes.length} episode · ${p.clips.length} klip pada proyek ini</small></div><button class="btn btn-primary" id="newEpisode">＋ Tambah episode</button></div>
 <div class="episode-list">${cards}</div>
 <div class="panel episode-editor"><div class="section-head" style="margin-top:0"><h3>Editor episode ${active?String(active.number).padStart(2,'0'):'—'}</h3><small>Perubahan disimpan pada proyek ini</small></div>
 ${active?`<div class="form-grid"><label>Nomor episode<input id="episodeNumber" type="number" min="1" max="999" value="${active.number}"></label><label>Judul episode<input id="episodeTitle" maxlength="120" value="${esc(active.title||'')}"></label></div>
 <label>Status episode<select id="episodeStatus"><option value="planning" ${active.status==='planning'?'selected':''}>Perencanaan</option><option value="story_approved" ${active.status==='story_approved'?'selected':''}>Cerita disetujui</option><option value="in_production" ${active.status==='in_production'?'selected':''}>Dalam produksi</option><option value="completed" ${active.status==='completed'?'selected':''}>Selesai</option><option value="archived" ${active.status==='archived'?'selected':''}>Arsip</option></select></label>
 <label>Sinopsis episode<textarea id="episodeSynopsis" rows="3" maxlength="4000">${esc(active.synopsis||'')}</textarea></label>
 <label>Master Storyline episode<textarea id="episodeMasterStoryline" rows="6" maxlength="12000" placeholder="Urutan cerita episode ini sesuai canon proyek.">${esc(active.masterStoryline||'')}</textarea></label>
 <label>Outline adegan — satu adegan per baris<textarea id="episodeOutline" rows="7" maxlength="12000" placeholder="KLIP 01 — JUDUL ADEGAN\nKLIP 02 — JUDUL ADEGAN">${esc(active.outline||'')}</textarea></label>
 <label>Catatan produksi episode<textarea id="episodeNotes" rows="3" maxlength="3000">${esc(active.notes||'')}</textarea></label>
 <div class="card-actions"><button class="btn btn-primary" id="saveEpisode">Simpan episode</button><button class="btn btn-outline" id="sendEpisodeOutline">Muat outline ke Storyboard Director →</button></div>`:'<p class="small-note">Belum ada episode untuk diedit.</p>'}
 <p class="small-note">Mengubah status menjadi Arsip tidak menghapus episode atau klip. Nomor episode yang sudah dipakai klip tidak dapat diubah agar relasi storyboard tidak terputus.</p></div>
 <p class="small-note">Modul ini mengelola canon dan struktur episode. AI penulis otomatis dan sinkronisasi video eksternal belum terhubung.</p>`;
}function continuityAudit(p){
 const clips=p.clips||[],chars=p.characters||[],issues=[];
 chars.forEach(c=>{
  const missing=[];
  if(!c.identity)missing.push('identitas/peran');
  if(!c.face)missing.push('ciri wajah');
  if(!c.hair)missing.push('rambut/penutup kepala');
  if(!c.costume)missing.push('busana');
  if(!c.accessories)missing.push('aksesori');
  if(!c.rules)missing.push('aturan kontinuitas');
  if(!(c.referenceFront||c.referenceImage))missing.push('referensi depan');
  if(!c.referenceSide)missing.push('referensi samping');
  if(!c.referenceFullBody)missing.push('referensi seluruh tubuh');
  if(missing.length)issues.push({level:'warning',title:c.name,detail:'Belum lengkap: '+missing.join(', ')});
 });
 const keys=new Map();
 clips.forEach(c=>{const key=(c.episodeNumber||1)+'-'+c.number;if(keys.has(key))issues.push({level:'danger',title:'Nomor klip ganda',detail:'Episode '+(c.episodeNumber||1)+' memiliki lebih dari satu klip bernomor '+c.number+'.'});else keys.set(key,c.id);
  const selected=(c.characterIds||[]).filter(id=>chars.some(x=>x.id===id));
  if(!c.visual)issues.push({level:'warning',title:'Deskripsi visual kosong',detail:'Episode '+(c.episodeNumber||1)+' · Klip '+c.number+' — '+(c.title||'Tanpa judul')});
  (c.characterIds||[]).filter(id=>!chars.some(x=>x.id===id)).forEach(()=>issues.push({level:'danger',title:'Referensi karakter terputus',detail:'Episode '+(c.episodeNumber||1)+' · Klip '+c.number+' memuat ID karakter yang tidak ditemukan.'}));
  if(!selected.length&&/tampil|terlihat|berdiri|berjalan|berbicara|menatap/i.test(c.visual||''))issues.push({level:'warning',title:'Periksa karakter layar',detail:'Episode '+(c.episodeNumber||1)+' · Klip '+c.number+' menyebut aksi/kehadiran tetapi belum memilih karakter tampil.'});
 });
 const danger=issues.filter(x=>x.level==='danger').length,warning=issues.filter(x=>x.level==='warning').length;
 const rows=issues.length?issues.map(x=>'<div class="audit-row"><span class="audit-level '+x.level+'">'+(x.level==='danger'?'PERLU DIBENAHI':'PERLU DICEK')+'</span><div><b>'+esc(x.title)+'</b><p>'+esc(x.detail)+'</p></div></div>').join(''):'<div class="empty"><strong>Belum ditemukan masalah pada pemeriksaan dasar.</strong>Ini bukan jaminan bahwa seluruh detail cerita dan visual sudah konsisten. Tetap periksa hasil render secara manual.</div>';
 return '<section class="panel continuity-audit"><div class="section-head" style="margin-top:0"><h3>Continuity Intelligence · Pemeriksaan dasar</h3><small>'+chars.length+' karakter · '+clips.length+' klip diperiksa</small></div><div class="audit-summary"><div><strong>'+danger+'</strong><span>Masalah prioritas</span></div><div><strong>'+warning+'</strong><span>Peringatan</span></div><div><strong>'+issues.length+'</strong><span>Total temuan</span></div></div><p class="small-note">Pemeriksaan otomatis ini memeriksa kelengkapan data dan struktur. Sistem belum dapat memastikan kemiripan wajah antar-gambar atau kontinuitas visual hasil Google Flow.</p><div class="audit-list">'+rows+'</div></section>';
}
function characters(p){if(!p)return empty('Pilih proyek','Buat atau pilih proyek terlebih dahulu.');return `${head('PRODUCTION BIBLE',`Master Character · ${esc(p.name)}`,'Catat identitas visual, voice mapping, dan aturan kontinuitas untuk setiap karakter.',`<button class="btn btn-primary" id="newCharacter">＋ Tambah karakter</button>`)}<div class="panel"><h3>Aturan kontinuitas</h3><p>Gunakan deskripsi dan referensi yang sama pada setiap klip. Catat perubahan kostum atau kondisi karakter sebagai pengecualian yang disengaja, bukan perubahan tidak sengaja.</p></div>${continuityAudit(p)}<div class="character-grid">${p.characters.map(c=>`<article class="character-card">${c.referenceImage?`<img class="character-reference-image" src="${c.referenceImage}" alt="Referensi ${esc(c.name)}" loading="lazy">`:`<div class="character-reference-placeholder">NO REFERENCE IMAGE</div>`}<div class="meta">CHARACTER REFERENCE</div><h3>${esc(c.name)}</h3><p>${esc(c.visual||'Belum ada deskripsi visual.')}</p><p><b>Identitas:</b> ${esc(c.identity||'Belum diisi')}<br><b>Wajah:</b> ${esc(c.face||'Belum diisi')}<br><b>Rambut:</b> ${esc(c.hair||'Belum diisi')}<br><b>Postur:</b> ${esc(c.body||'Belum diisi')}<br><b>Busana:</b> ${esc(c.costume||'Belum diisi')}<br><b>Aksesori:</b> ${esc(c.accessories||'Belum diisi')}</p><div class="tag">VOICE · ${esc(c.voice||'Belum ditentukan')} · REFERENCES ${(c.referenceFront||c.referenceImage?1:0)+(c.referenceSide?1:0)+(c.referenceFullBody?1:0)}/3</div><p><b>Kontinuitas:</b> ${esc(c.rules||'Belum ditentukan')}</p><div class="card-actions">${c.referenceImage?`<button class="btn btn-outline btn-small" data-download-character="${c.id}">Unduh depan</button>`:""}${c.referenceSide?`<button class="btn btn-outline btn-small" data-download-character-side="${c.id}">Unduh samping</button>`:""}${c.referenceFullBody?`<button class="btn btn-outline btn-small" data-download-character-full="${c.id}">Unduh seluruh tubuh</button>`:""}<button class="btn btn-outline btn-small" data-edit-character="${c.id}">Ubah</button><button class="btn btn-outline btn-small danger" data-delete-character="${c.id}">Hapus</button></div></article>`).join('')||empty('Belum ada karakter','Tambahkan karakter utama beserta deskripsi visual dan suaranya.')}</div>`}
function promptQualityAudit(c,p){
 const chars=p.characters||[],issues=[],selected=(c.characterIds||[]).map(id=>chars.find(x=>x.id===id)).filter(Boolean),voices=(c.voiceCharacterIds||[]).map(id=>chars.find(x=>x.id===id)).filter(Boolean);
 const label='Episode '+(c.episodeNumber||1)+' · Klip '+c.number+' — '+(c.title||'Tanpa judul');
 if((c.dialogue||'').trim()&&!voices.length)issues.push({level:'warning',title:'Dialog belum memiliki voice mapping',detail:'Dialog sudah diisi, tetapi belum ada karakter/suara yang dipilih pada voice mapping.'});
 (c.voiceCharacterIds||[]).filter(id=>!chars.some(x=>x.id===id)).forEach(()=>issues.push({level:'danger',title:'Voice mapping terputus',detail:'Ada ID suara yang tidak lagi cocok dengan Master Character.'}));
 selected.filter(x=>!isNarrator(x)).forEach(x=>{const missing=[];if(!x.face)missing.push('ciri wajah');if(!x.costume)missing.push('busana');if(!(x.referenceFront||x.referenceImage))missing.push('referensi depan');if(!x.referenceSide)missing.push('referensi samping');if(!x.referenceFullBody)missing.push('referensi seluruh tubuh');if(missing.length)issues.push({level:'warning',title:'Referensi '+x.name+' belum lengkap',detail:'Belum tersedia: '+missing.join(', ')+'.'});});
 const textToCheck=[c.visual,c.lighting,c.shot,c.motion].filter(Boolean).join(' ').toLowerCase();
 const has=(re)=>re.test(textToCheck);
 if(has(/\b(siang|pagi|fajar|matahari|daylight|sunlit)\b/)&&has(/\b(malam|tengah malam|nighttime|moonlit|gelap gulita)\b/))issues.push({level:'warning',title:'Kemungkinan konflik waktu',detail:'Arahan memuat petunjuk siang/pagi sekaligus malam. Pastikan ini memang transisi yang disengaja.'});
 if(has(/\b(dalam ruangan|interior|di dalam|indoor)\b/)&&has(/\b(luar ruangan|eksterior|di luar|outdoor)\b/))issues.push({level:'warning',title:'Kemungkinan konflik lokasi',detail:'Arahan memuat interior sekaligus eksterior. Perjelas apakah adegan berpindah lokasi atau hanya satu ruang.'});
 const rows=issues.length?issues.map(x=>'<div class="audit-row"><span class="audit-level '+x.level+'">'+(x.level==='danger'?'PRIORITAS':'PERIKSA')+'</span><div><b>'+esc(x.title)+'</b><p>'+esc(x.detail)+'</p></div></div>').join(''):'<div class="empty"><strong>Tidak ditemukan konflik dasar.</strong> Tetap tinjau prompt dan hasil render secara manual.</div>';
 return '<section class="panel continuity-audit"><div class="section-head" style="margin-top:0"><h3>Prompt Quality Control · '+esc(label)+'</h3><small>'+issues.length+' temuan</small></div><p class="small-note">Pemeriksaan konservatif sebelum prompt disalin. Hanya memberi peringatan; tidak mengubah atau memblokir data. Tidak dapat membuktikan kemiripan wajah maupun kontinuitas hasil render.</p><div class="audit-list">'+rows+'</div></section>';
}
function storyboard(p){if(!p)return empty('Pilih proyek','Buat atau pilih proyek terlebih dahulu.');return `${head('SHOT & SCENE DESIGN',`Storyboard · ${esc(p.name)}`,'Buat klip per adegan. Setiap klip memiliki deskripsi visual, gerakan kamera, audio, dan prompt yang dapat disalin.',`<button class="btn btn-primary" id="newClip">＋ Tambah klip</button>`)}<div class="panel storyboard-director"><div class="section-head" style="margin-top:0"><h3>AI Storyboard Director · Draft Builder</h3><small>Ubah daftar adegan Master Storyline menjadi draft klip</small></div><p class="small-note">Masukkan satu adegan per baris. Sistem membuat draft yang dapat diperiksa dan disunting; tidak mengarang dialog, karakter, atau detail cerita yang belum diberikan.</p><div class="form-grid"><label>Nomor episode<input id="directorEpisodeNumber" type="number" min="1" value="1"></label><label>Judul episode<input id="directorEpisodeTitle" maxlength="100" placeholder="Contoh: Kerajaan Seri Bunga Tanjung"></label></div><label>Durasi setiap klip (detik)<input id="directorDuration" type="number" min="1" max="120" value="10"></label><label>Daftar adegan — satu adegan per baris<textarea id="directorScenes" rows="7" placeholder="KLIP 01 — NEGERI SERI BUNGA TANJUNG&#10;KLIP 02 — ISTANA KERAJAAN MELAYU&#10;KLIP 03 — KEHIDUPAN KERAJAAN"></textarea></label><button class="btn btn-primary" id="generateStoryboard">＋ Buat draft klip</button><div id="directorStatus" class="small-note" aria-live="polite">Draft baru ditambahkan tanpa menghapus klip yang sudah ada.</div></div><div class="panel"><div class="section-head" style="margin-top:0"><h3>Prompt Generator</h3><small>${new Set(p.clips.map(x=>x.episodeNumber||1)).size} episode · ${p.clips.length} klip tersusun</small></div><label>Pilih klip untuk menyusun prompt<select id="promptClip"><option value="">Pilih klip storyboard...</option>${p.clips.map(c=>`<option value="${c.id}">${String(c.number).padStart(2,'0')} · ${esc(c.title)}</option>`).join('')}</select></label><div id="promptQualityOutput" class="prompt-quality-output"><p class="small-note">Pilih klip untuk menjalankan pemeriksaan prompt.</p></div><div class="section-head"><h3>Visual Production Prompt</h3></div><div id="promptOutput" class="prompt-box">Pilih salah satu klip untuk menghasilkan prompt visual.</div><div class="prompt-tools"><button class="btn btn-primary btn-small" id="copyPrompt" disabled>Salin prompt visual</button><button class="btn btn-outline btn-small" id="downloadPrompt" disabled>Unduh visual .txt</button></div><div class="section-head"><h3>Audio Production Prompt</h3></div><div id="audioPromptOutput" class="prompt-box">Audio cue sheet akan tampil setelah klip dipilih.</div><div class="prompt-tools"><button class="btn btn-primary btn-small" id="copyAudioPrompt" disabled>Salin prompt audio</button><button class="btn btn-outline btn-small" id="downloadAudioPrompt" disabled>Unduh audio .txt</button></div></div><div class="section-head"><h3>Daftar klip</h3><small>Urut berdasarkan nomor klip</small></div><div class="clip-list">${[...p.clips].sort((a,b)=>(a.episodeNumber||1)-(b.episodeNumber||1)||a.number-b.number).map(c=>`<article class="clip-card"><div class="clip-number">${String(c.number).padStart(2,'0')}</div><div><h3>${esc(c.title)}</h3><p><b>${esc(c.episodeTitle||('Episode '+(c.episodeNumber||1)))}</b> · Klip ${String(c.number).padStart(2,'0')} · ${c.duration}s</p><p>${esc(c.visual||'Belum ada deskripsi visual.')}</p></div><div class="clip-actions"><button class="btn btn-outline btn-small" data-edit-clip="${c.id}">Ubah</button><button class="btn btn-outline btn-small" data-use-clip="${c.id}">Prompt</button><button class="icon-btn danger" data-delete-clip="${c.id}" aria-label="Hapus klip">×</button></div></article>`).join('')||empty('Storyboard masih kosong','Tambahkan klip pertama untuk mulai menyusun adegan.')}</div>`}
function engines(){return `${head('AI CONNECTIVITY','AI Engine','Pilih alur kerja manual sekarang; koneksi otomatis hanya diaktifkan setelah API resmi, izin, keamanan, dan biaya diverifikasi.')}<div class="panel"><h3>Google Flow · Mode manual aktif</h3><p>Lehan AI Film Studio menyiapkan prompt, daftar referensi karakter, arahan kamera, kontinuitas, ambience dan SFX. Salin prompt, unduh gambar karakter, lalu lampirkan secara manual di Google Flow untuk rendering.</p><div class="tag">READY FOR MANUAL WORKFLOW</div></div><div class="panel"><h3>Mode hybrid · API-ready, belum terhubung</h3><p>Struktur proyek mendukung rencana integrasi provider melalui API resmi. Tidak ada rendering otomatis yang berjalan saat ini. API key tidak boleh disimpan di browser atau di dalam file JavaScript aplikasi.</p><div class="tag">AUTOMATION NOT CONNECTED</div></div><div class="engine-grid">${[['Runway','Video generation API','docs.dev.runwayml.com'],['Luma','Video and image generation API','docs.agents.lumalabs.ai'],['Kling AI','Periksa akses API resmi dan ketentuan akun','kling.ai'],['Voice provider','Narasi dan dialog karakter','']].map((e,i)=>`<article class="engine-card"><div class="engine-icon">${['▶','✧','◉','♫'][i]}</div><div><h3>${e[0]}</h3><p>${e[1]}</p><div class="status">● BELUM TERHUBUNG</div>${e[2]?`<p><a href="https://${e[2]}" target="_blank" rel="noreferrer" style="color:var(--gold2)">Situs / dokumentasi ↗</a></p>`:''}</div></article>`).join('')}</div><p class="small-note">Status “belum terhubung” berarti aplikasi belum mengirim permintaan rendering ke provider. Ketersediaan API, model, wilayah, biaya, dan izin harus diverifikasi sebelum integrasi.</p>`}
function empty(title,desc){return `<div class="empty"><strong>${title}</strong>${desc}</div>`}
function buildPrompt(c,p){
 const b=normalizeBible(p),chars=p.characters||[];
 const selectedVisual=(c.characterIds||[]).map(id=>chars.find(x=>x.id===id)).filter(Boolean);
 const selectedVoice=(c.voiceCharacterIds||[]).map(id=>chars.find(x=>x.id===id)).filter(Boolean);
 const visualChars=selectedVisual.filter(x=>!isNarrator(x));
 const voiceChars=[...new Map([...selectedVoice,...selectedVisual.filter(isNarrator)].map(x=>[x.id,x])).values()];
 const characterSection=visualChars.length?visualChars.map(x=>[
  'ON-SCREEN CHARACTER — '+x.name,
  'Identity / role: '+(x.identity||'Use the approved Master Character Sheet.'),
  'Face identity: '+(x.face||'Preserve the attached approved face reference exactly; do not redesign.'),
  'Hair / headwear: '+(x.hair||'Preserve the approved reference.'),
  'Body / posture: '+(x.body||'Preserve the approved proportions and posture.'),
  'Costume: '+(x.costume||'Preserve the approved costume; no substitutions.'),
  'Accessories: '+(x.accessories||'Preserve approved accessories.'),
  'Visual description: '+(x.visual||'No additional visual description supplied.'),
  'Continuity rules: '+(x.rules||'Preserve the approved character reference without alteration.'),
  'Identity priority: attached approved reference images override any ambiguous text description.'
 ].join('\n')).join('\n\n'):'NO SELECTED ON-SCREEN CHARACTERS. Show only people explicitly required by the scene description; do not invent, duplicate, or import characters from another scene.';
 const referenceHandoff=visualChars.length?visualChars.map(x=>{const views=[x.referenceFront||x.referenceImage,x.referenceSide,x.referenceFullBody].filter(Boolean).length;return '- '+x.name+': '+views+'/3 saved reference views. Download and manually attach every available approved view in Google Flow before rendering. Front/side/full-body views are not uploaded automatically.';}).join('\n'):'No on-screen character reference attachment is selected for this clip.';
 const voiceSection=voiceChars.length?voiceChars.map(x=>{const onScreen=visualChars.some(v=>v.id===x.id);return '- '+x.name+': '+(onScreen?'VOICE OF A SELECTED ON-SCREEN CHARACTER — do not infer lip-sync or visible speaking unless explicitly directed.':'OFF-SCREEN VOICE / NARRATION — audio only; do not render this speaker.')+' Voice preset: '+(x.voice||'Not specified')+'. Performance/continuity notes: '+(x.rules||'Follow the approved voice mapping; do not change voice identity.');}).join('\n'):'No voice mapping selected. Do not invent a speaker, narration, dialogue, or lip-sync.';
 const dialogue=c.dialogue||'NO DIALOGUE. Do not create spoken words, vocalizations, or lip-sync.';
 const audioNote=c.audio||'Audio is handled separately in the Audio Production Cue Sheet and final CapCut mix.';
 return [
 'PROMPT ENGINE 2.0 — VISUAL GENERATION BRIEF',
 'PROJECT: '+p.name,
 'WORKSPACE: '+(p.workspaceType==='lpp'?'LPP STUDIO — obey this project’s approved LPP Master Bible and character canon only.':'CREATOR STUDIO — obey only this project’s own approved creative bible; do not import LPP story, characters, dialect, or visual canon.'),
 'WORKFLOW: '+(p.generationMode==='hybrid'?'HYBRID — prepare a manual Google Flow prompt. No automatic rendering/API connection is active.':'MANUAL — copy this prompt and render manually in Google Flow or the selected engine.'),
 '', 'A. APPROVED PROJECT CANON',
 'Setting: '+(b.setting||'Not specified.'),
 'Visual style / format: '+(b.visualStyle||'Not specified.'),
 'Language and dialogue rules: '+(b.languageRules||'Not specified.'),
 'Global continuity rules: '+(b.continuity||'Not specified.'),
 '', 'B. SCENE IDENTIFICATION',
 'Episode '+(c.episodeNumber||1)+': '+(c.episodeTitle||'Episode '+(c.episodeNumber||1)),
 'Scene '+String(c.number).padStart(2,'0')+': '+(c.title||'Untitled scene'),
 'Duration: '+(c.duration||'Not specified')+' seconds',
 'Frame: 16:9 cinematic composition.',
 '', 'C. SCENE CONTENT — SOURCE OF TRUTH',
 c.visual||'Scene visual description has not been supplied. Do not invent plot events or character actions.',
 '', 'D. CINEMATOGRAPHY',
 'Shot size / composition: '+(c.shot||'Choose a clear cinematic composition that serves only the described scene.'),
 'Camera movement / on-screen action: '+(c.motion||'Use restrained, motivated camera movement. Do not add actions not stated in the scene.'),
 'Lighting / color grade: '+(c.lighting||b.visualStyle||'Maintain natural, coherent lighting and the approved project color language.'),
 'End frame / transition: '+(c.transition||'End on a stable, coherent frame; do not introduce a new event.'),
 '', 'E. ON-SCREEN CHARACTER LOCK',characterSection,
 '', 'F. REFERENCE IMAGE HANDOFF — MANUAL',referenceHandoff,
 'This workspace does not transmit images to Google Flow. Attach the approved reference files yourself before rendering. Never claim a reference is attached when it is not.',
 '', 'G. VOICE CAST — AUDIO ROLE ONLY',voiceSection,
 'Exact dialogue supplied for this scene: '+dialogue,
 'Dialogue language must follow the approved Master Bible. Do not translate, paraphrase, extend, or improvise the supplied dialogue.',
 '', 'H. SOUND INTENT — OPTIONAL ENGINE GUIDANCE',
 'General audio direction: '+audioNote,
 'Ambience / SFX: '+(c.sfx||'No specific ambience or action SFX supplied. Do not invent a sound tied to an event that is not shown.'),
 'Music: '+(c.music||'No music generation requested. Add the approved score in the editing stage if needed.'),
 'Use the separate Audio Production Cue Sheet as the authoritative detailed sound-design and CapCut mixing plan. Do not let audio instructions alter the visual scene.',
 '', 'I. NON-NEGOTIABLE CONTINUITY / NEGATIVE CONSTRAINTS',
 'Preserve the exact approved face identity, facial proportions, age appearance, hairstyle, costume, accessories, body proportions, and character identity. No face morphing, beautification redesign, costume/color substitutions, missing or added accessories, duplicate people, extra characters, unintended crowd, scene/time/weather changes, flicker, warped anatomy, text, subtitles, logos, or watermarks. Preserve established environment, lighting logic, and color grade across adjacent clips.',
 '', 'J. SOURCE DISCIPLINE',
 'Use only facts and actions explicitly present in this scene and approved project canon. If a detail is missing, keep it neutral or omit it. Do not invent plot, dialogue, props, locations, character relationships, or camera-visible actions. A prompt is an instruction only; it does not mean a render or audio has already been generated.'
 ].join('\n');
}
function buildAudioPrompt(c,p){
 const chars=p.characters||[],b=normalizeBible(p);
 const voices=(c.voiceCharacterIds||[]).map(id=>chars.find(x=>x.id===id)).filter(Boolean);
 const visualIds=new Set((c.characterIds||[]).map(id=>chars.find(x=>x.id===id)).filter(x=>x&&!isNarrator(x)).map(x=>x.id));
 const voiceMap=voices.length?voices.map(x=>'- '+x.name+' — '+(visualIds.has(x.id)?'voice of selected on-screen character; visible speech/lip-sync only if explicitly directed':'off-screen voice / narration')+'; preset: '+(x.voice||'not specified')+'; performance notes: '+(x.rules||'follow approved voice identity; do not imitate another character')).join('\n'):'Tidak ada voice mapping yang dipilih. Jangan menciptakan narator atau suara karakter.';
 const dialogue=c.dialogue||'Tidak ada dialog. Jangan menciptakan kalimat, gumaman, tawa, atau lip-sync.';
 return [
 'AUDIO PRODUCTION CUE SHEET 2.0',
 'PROJECT: '+p.name,
 'WORKSPACE: '+(p.workspaceType==='lpp'?'LPP — follow approved LPP language and voice canon.':'CREATOR — follow this project’s own language and voice rules only.'),
 'EPISODE '+(c.episodeNumber||1)+': '+(c.episodeTitle||'Episode '+(c.episodeNumber||1)),
 'SCENE '+String(c.number).padStart(2,'0')+': '+(c.title||'Untitled scene'),
 'DURATION: '+(c.duration||'Not specified')+' seconds',
 '', '1. MUSIC / BGM',c.bgm||c.music||'No music specified. Add or compose the final score in CapCut only if required by the approved scene direction.',
 '', '2. ENVIRONMENTAL AMBIENCE',c.ambience||'Not specified. Do not invent a location-specific ambience without scene evidence.',
 '', '3. TIMED SOUND EFFECTS (SFX)',c.sfxCues||c.sfx||'No specific SFX cues supplied. Do not add action sounds for events that are not visible or stated.',
 '', '4. FOLEY / PHYSICAL DETAIL',c.foley||'Use only when visually motivated: footsteps matching the surface, cloth movement, jewelry movement, breathing, contact, or object handling.',
 '', '5. EXACT DIALOGUE / VOICE','Exact dialogue: '+dialogue,'Language / dialect: '+(b.languageRules||'Follow the project’s approved language rules.'),'Voice mapping:',voiceMap,
 'Do not translate, paraphrase, extend, or improvise the exact dialogue. If no dialogue is supplied, keep the scene silent apart from specified ambience/SFX/music.',
 '', '6. MIXING / SPATIAL PERSPECTIVE',c.mix||c.audio||'Keep dialogue intelligible when present; ambience sits behind the action; synchronize SFX with visible action; preserve natural distance, stereo perspective, dynamics, and headroom.',
 '', '7. TRANSITION / AUDIO BRIDGE',c.transition||'End naturally and prepare a restrained audio bridge to the next clip only when continuity requires it.',
 '', '8. CAPCUT POST-PRODUCTION',
 'Keep BGM, ambience, SFX, Foley, and dialogue on separate stems/tracks where possible. Align cues to the clip timeline and visible action. Control peaks and avoid masking dialogue. Google Flow may not generate every audio layer; use this cue sheet for manual sound design and mixing in CapCut. This is a production plan, not a claim that audio has been generated.'
 ].join('\n');
}
function bindDynamic(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.go));const readMasterStory=()=>({logline:$('#storyLogline').value.trim(),synopsis:$('#storySynopsis').value.trim(),conflict:$('#storyConflict').value.trim(),themes:$('#storyThemes').value.trim(),notes:$('#storyNotes').value.trim()});const saveStory=$('#saveStoryDevelopment');if(saveStory)saveStory.onclick=()=>{project().storyDevelopment={...(project().storyDevelopment||{}),...readMasterStory()};if(save())toast('Master Storyline tersimpan.');};const newEpisode=$('#newEpisode');if(newEpisode)newEpisode.onclick=()=>{const p=project(),eps=getProjectEpisodes(p),number=Math.max(0,...eps.map(x=>Number(x.number)||0))+1;const ep={id:uid(),number,title:'Episode '+number,synopsis:'',masterStoryline:'',outline:'',status:'planning',notes:''};eps.push(ep);editingEpisodeId=ep.id;if(save()){render();toast('Episode baru ditambahkan.');}};document.querySelectorAll('[data-edit-episode]').forEach(b=>b.onclick=()=>{editingEpisodeId=b.dataset.editEpisode;render()});const readEpisode=()=>({number:Math.max(1,Number($('#episodeNumber').value)||1),title:$('#episodeTitle').value.trim(),status:$('#episodeStatus').value,synopsis:$('#episodeSynopsis').value.trim(),masterStoryline:$('#episodeMasterStoryline').value.trim(),outline:$('#episodeOutline').value.trim(),notes:$('#episodeNotes').value.trim()});const saveEpisode=$('#saveEpisode');if(saveEpisode)saveEpisode.onclick=()=>{const p=project(),ep=getProjectEpisodes(p).find(x=>x.id===editingEpisodeId);if(!ep)return;const data=readEpisode(),used=p.clips.some(c=>(Number(c.episodeNumber)||1)===Number(ep.number));if(used&&data.number!==ep.number){toast('Nomor episode tidak dapat diubah karena sudah dipakai klip storyboard.');return;}if(getProjectEpisodes(p).some(x=>x.id!==ep.id&&Number(x.number)===data.number)){toast('Nomor episode sudah digunakan. Pilih nomor lain.');return;}if(!data.title){toast('Judul episode wajib diisi.');return;}Object.assign(ep,data);if(save()){render();toast('Data episode tersimpan.');}};const sendEpisodeOutline=$('#sendEpisodeOutline');if(sendEpisodeOutline)sendEpisodeOutline.onclick=()=>{const p=project(),ep=getProjectEpisodes(p).find(x=>x.id===editingEpisodeId);if(!ep)return;const data=readEpisode();Object.assign(ep,data);if(!data.outline){toast('Isi outline adegan terlebih dahulu.');return;}if(!save())return;setView('storyboard');$('#directorEpisodeNumber').value=ep.number;$('#directorEpisodeTitle').value=ep.title;$('#directorScenes').value=ep.outline;toast('Outline episode dimuat ke Storyboard Director. Periksa sebelum membuat klip.');};const np=$('#newProject');if(np)np.onclick=()=>openProject();document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>{state.activeProjectId=b.dataset.openProject;save();setView('dashboard')});document.querySelectorAll('[data-edit-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.editProject));document.querySelectorAll('[data-delete-project]').forEach(b=>b.onclick=()=>{if(state.projects.length===1)return toast('Minimal satu proyek harus tersedia.');if(confirm('Hapus proyek beserta seluruh karakter dan storyboard?')){state.projects=state.projects.filter(p=>p.id!==b.dataset.deleteProject);if(state.activeProjectId===b.dataset.deleteProject)state.activeProjectId=state.projects[0].id;save();render();toast('Proyek dihapus.')}});
const nc=$('#newCharacter');if(nc)nc.onclick=()=>openCharacter();document.querySelectorAll('[data-download-character]').forEach(b=>b.onclick=()=>{const character=project().characters.find(x=>x.id===b.dataset.downloadCharacter);if(character?.referenceImage)downloadDataUrl(`${character.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-reference.jpg`,character.referenceImage)});
document.querySelectorAll('[data-download-character-side]').forEach(b=>b.onclick=()=>{const x=project().characters.find(x=>x.id===b.dataset.downloadCharacterSide);if(x?.referenceSide)downloadDataUrl(x.name+'-side.jpg',x.referenceSide)});
document.querySelectorAll('[data-download-character-full]').forEach(b=>b.onclick=()=>{const x=project().characters.find(x=>x.id===b.dataset.downloadCharacterFull);if(x?.referenceFullBody)downloadDataUrl(x.name+'-full-body.jpg',x.referenceFullBody)});document.querySelectorAll('[data-edit-character]').forEach(b=>b.onclick=()=>openCharacter(b.dataset.editCharacter));document.querySelectorAll('[data-delete-character]').forEach(b=>b.onclick=()=>{if(confirm('Hapus karakter ini?')){const p=project();p.characters=p.characters.filter(c=>c.id!==b.dataset.deleteCharacter);p.clips.forEach(c=>{c.characterIds=c.characterIds.filter(id=>id!==b.dataset.deleteCharacter);c.voiceCharacterIds=(c.voiceCharacterIds||[]).filter(id=>id!==b.dataset.deleteCharacter)});save();render()}});
const ncl=$('#newClip');if(ncl)ncl.onclick=()=>openClip();const generateStoryboard=$('#generateStoryboard');if(generateStoryboard)generateStoryboard.onclick=()=>{const scenes=$('#directorScenes').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!scenes.length){$('#directorStatus').textContent='Masukkan minimal satu adegan, masing-masing pada baris terpisah.';return}const episodeNumber=Math.max(1,Number($('#directorEpisodeNumber').value)||1),episodeTitle=$('#directorEpisodeTitle').value.trim()||('Episode '+episodeNumber),duration=Math.min(120,Math.max(1,Number($('#directorDuration').value)||10));const existing=project().clips.filter(c=>(c.episodeNumber||1)===episodeNumber);let next=Math.max(0,...existing.map(c=>Number(c.number)||0))+1;const used=new Set(existing.map(c=>Number(c.number)));const drafts=scenes.map((line,index)=>{const match=line.match(/^(?:KLIP|CLIP)\s*0*(\d+)\s*[—–:-]?\s*/i),title=line.replace(/^(?:KLIP|CLIP)\s*0*\d+\s*[—–:-]?\s*/i,'').trim()||line;let number=match?Number(match[1]):next+index;while(used.has(number))number++;used.add(number);return{id:uid(),episodeNumber,episodeTitle,number,duration,title,visual:'Adegan berdasarkan Master Storyline: '+title+'. Kembangkan visual hanya sesuai informasi cerita yang disetujui; jangan menambahkan peristiwa baru.',shot:'Pilih shot size dan komposisi yang jelas; pertahankan format sinematik 16:9.',motion:'Gerakan kamera halus dan termotivasi oleh aksi adegan. Jangan menambahkan aksi yang tidak tercantum.',lighting:'Ikuti Master Bible dan kesinambungan color grading antar-klip.',dialogue:'',sfx:'',music:'',bgm:'',ambience:'',sfxCues:'',foley:'',mix:'',transition:'Akhiri pada frame koheren untuk disambungkan ke adegan berikutnya.',audio:'',characterIds:[],voiceCharacterIds:[]}});project().clips.push(...drafts);save();render();toast(drafts.length+' draft klip berhasil dibuat. Periksa dan lengkapi setiap klip.');};document.querySelectorAll('[data-edit-clip]').forEach(b=>b.onclick=()=>openClip(b.dataset.editClip));document.querySelectorAll('[data-delete-clip]').forEach(b=>b.onclick=()=>{if(confirm('Hapus klip ini?')){project().clips=project().clips.filter(c=>c.id!==b.dataset.deleteClip);save();render()}});document.querySelectorAll('[data-use-clip]').forEach(b=>b.onclick=()=>{const s=$('#promptClip');s.value=b.dataset.useClip;s.dispatchEvent(new Event('change'));$('#promptOutput').scrollIntoView({behavior:'smooth',block:'center'})});
const ps=$('#promptClip');if(ps)ps.onchange=()=>{const c=project().clips.find(x=>x.id===ps.value);$('#promptOutput').textContent=c?buildPrompt(c,project()):'Pilih salah satu klip untuk menghasilkan prompt visual.';$('#audioPromptOutput').textContent=c?buildAudioPrompt(c,project()):'Audio cue sheet akan tampil setelah klip dipilih.';$('#promptQualityOutput').innerHTML=c?promptQualityAudit(c,project()):'<p class="small-note">Pilih klip untuk menjalankan pemeriksaan prompt.</p>';$('#copyPrompt').disabled=!c;$('#downloadPrompt').disabled=!c;$('#copyAudioPrompt').disabled=!c;$('#downloadAudioPrompt').disabled=!c};const cp=$('#copyPrompt');if(cp)cp.onclick=async()=>{try{await navigator.clipboard.writeText($('#promptOutput').textContent);toast('Prompt berhasil disalin.')}catch{toast('Clipboard tidak tersedia pada browser ini.')}};const dl=$('#downloadPrompt');if(dl)dl.onclick=()=>downloadText(`prompt-klip-${$('#promptClip').selectedOptions[0].textContent.split(' · ')[0]}.txt`,$('#promptOutput').textContent)}
function openProject(id){editingProject=id||null;const p=state.projects.find(x=>x.id===id);$('#projectDialogTitle').textContent=p?'Ubah proyek':'Proyek baru';$('#projectName').value=p?.name||'';$('#projectDescription').value=p?.description||'';$('#projectGenre').value=p?.genre||'';$('#projectType').value=p?.workspaceType||'creator';$('#generationMode').value=p?.generationMode||'hybrid';const bible=p?.masterBible||{};$('#bibleSetting').value=bible.setting||'';$('#bibleVisual').value=bible.visualStyle||'';$('#bibleLanguage').value=bible.languageRules||'';$('#bibleContinuity').value=bible.continuity||'';$('#projectDialog').showModal()}
