function renderCharacterImagePreview(){const box=$('#characterImagePreview');if(!box)return;box.innerHTML=pendingCharacterImage?'<img src="'+pendingCharacterImage+'" alt="Preview referensi karakter">':'Belum ada gambar referensi.'}
$('#characterImage').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Pilih file gambar yang valid.');return}try{pendingCharacterImage=await compressCharacterImage(file);pendingCharacterImages.front=pendingCharacterImage;renderCharacterImagePreview();toast('Referensi depan siap disimpan.')}catch(err){toast('Gambar tidak dapat diproses.')}};
function renderCharacterAnglePreviews(){[['side','characterSidePreview'],['fullBody','characterFullBodyPreview']].forEach(([key,id])=>{const el=$('#'+id);if(el)el.innerHTML=pendingCharacterImages[key]?'<img src="'+pendingCharacterImages[key]+'" alt="Referensi '+key+'">':'Belum ada gambar.'})}
$('#characterSideImage').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{pendingCharacterImages.side=await compressCharacterImage(file);renderCharacterAnglePreviews()}catch(err){toast('Referensi samping gagal diproses.')}};
$('#characterFullBodyImage').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{pendingCharacterImages.fullBody=await compressCharacterImage(file);renderCharacterAnglePreviews()}catch(err){toast('Referensi seluruh tubuh gagal diproses.')}};
$('#removeCharacterSideImage').onclick=()=>{pendingCharacterImages.side='';$('#characterSideImage').value='';renderCharacterAnglePreviews()};
$('#removeCharacterFullBodyImage').onclick=()=>{pendingCharacterImages.fullBody='';$('#characterFullBodyImage').value='';renderCharacterAnglePreviews()};
$('#removeCharacterImage').onclick=()=>{pendingCharacterImage='';if(typeof pendingCharacterImages!=='undefined')pendingCharacterImages.front='';$('#characterImage').value='';renderCharacterImagePreview()};
function compressCharacterImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const max=900,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.76))};img.src=reader.result};reader.readAsDataURL(file)})}
let pendingCharacterImages={front:'',side:'',fullBody:''};
function openCharacter(id){editingCharacter=id||null;const c=project().characters.find(x=>x.id===id);$('#characterDialogTitle').textContent=c?'Ubah karakter':'Karakter baru';$('#characterName').value=c?.name||'';pendingCharacterImages={front:c?.referenceFront||c?.referenceImage||'',side:c?.referenceSide||'',fullBody:c?.referenceFullBody||''};pendingCharacterImage=pendingCharacterImages.front;renderCharacterImagePreview();$('#characterImage').value='';$('#characterSideImage').value='';$('#characterFullBodyImage').value='';$('#characterIdentity').value=c?.identity||'';$('#characterFace').value=c?.face||'';$('#characterHair').value=c?.hair||'';$('#characterBody').value=c?.body||'';$('#characterCostume').value=c?.costume||'';$('#characterAccessories').value=c?.accessories||'';$('#characterVisual').value=c?.visual||'';$('#characterVoice').value=c?.voice||'';$('#characterRules').value=c?.rules||'';renderCharacterAnglePreviews();$('#characterDialog').showModal()}
$('#characterForm').onsubmit=e=>{e.preventDefault();const data={name:$('#characterName').value.trim(),identity:$('#characterIdentity').value.trim(),face:$('#characterFace').value.trim(),hair:$('#characterHair').value.trim(),body:$('#characterBody').value.trim(),costume:$('#characterCostume').value.trim(),accessories:$('#characterAccessories').value.trim(),visual:$('#characterVisual').value.trim(),voice:$('#characterVoice').value.trim(),rules:$('#characterRules').value.trim(),referenceFront:pendingCharacterImages.front||pendingCharacterImage,referenceSide:pendingCharacterImages.side,referenceFullBody:pendingCharacterImages.fullBody,referenceImage:pendingCharacterImages.front||pendingCharacterImage};const p=project();let c=p.characters.find(x=>x.id===editingCharacter);if(c)Object.assign(c,data);else p.characters.push({id:uid(),...data});save();$('#characterDialog').close();render();toast('Master Character Sheet tersimpan.')};
function openClip(id){editingClip=id||null;const c=project().clips.find(x=>x.id===id);$('#clipDialogTitle').textContent=c?'Ubah klip':'Klip baru';$('#clipEpisodeNumber').value=c?.episodeNumber??1;$('#clipEpisodeTitle').value=c?.episodeTitle||'Episode 1';$('#clipNumber').value=c?.number??(Math.max(0,...project().clips.filter(x=>(x.episodeNumber||1)===(c?.episodeNumber||1)).map(x=>x.number))+1);$('#clipDuration').value=c?.duration??10;$('#clipTitle').value=c?.title||'';$('#clipVisual').value=c?.visual||'';$('#clipShot').value=c?.shot||'';$('#clipLighting').value=c?.lighting||'';$('#clipMotion').value=c?.motion||'';$('#clipDialogue').value=c?.dialogue||'';$('#clipSfx').value=c?.sfx||'';$('#clipMusic').value=c?.music||'';$('#clipTransition').value=c?.transition||'';$('#clipAudio').value=c?.audio||'';$('#clipBgm').value=c?.bgm||c?.music||'';$('#clipAmbience').value=c?.ambience||'';$('#clipSfxCues').value=c?.sfxCues||c?.sfx||'';$('#clipFoley').value=c?.foley||'';$('#clipMix').value=c?.mix||c?.audio||'';$('#clipCharacters').innerHTML=project().characters.filter(x=>!isNarrator(x)).map(x=>`<option value="${x.id}" ${(c?.characterIds||[]).includes(x.id)?'selected':''}>${esc(x.name)}</option>`).join('');$('#clipVoiceCharacters').innerHTML=project().characters.map(x=>`<option value="${x.id}" ${((c?.voiceCharacterIds||[]).includes(x.id)||((c?.characterIds||[]).includes(x.id)&&isNarrator(x)))?'selected':''}>${esc(x.name)}</option>`).join('');$('#clipDialog').showModal()}
$('#clipForm').onsubmit=e=>{e.preventDefault();const p=project(),data={episodeNumber:Number($('#clipEpisodeNumber').value)||1,episodeTitle:$('#clipEpisodeTitle').value.trim()||('Episode '+($('#clipEpisodeNumber').value||1)),number:Number($('#clipNumber').value),duration:Number($('#clipDuration').value),title:$('#clipTitle').value.trim(),visual:$('#clipVisual').value.trim(),shot:$('#clipShot').value.trim(),lighting:$('#clipLighting').value.trim(),motion:$('#clipMotion').value.trim(),dialogue:$('#clipDialogue').value.trim(),sfx:$('#clipSfx').value.trim(),music:$('#clipMusic').value.trim(),transition:$('#clipTransition').value.trim(),audio:$('#clipAudio').value.trim(),bgm:$('#clipBgm').value.trim(),ambience:$('#clipAmbience').value.trim(),sfxCues:$('#clipSfxCues').value.trim(),foley:$('#clipFoley').value.trim(),mix:$('#clipMix').value.trim(),characterIds:[...$('#clipCharacters').selectedOptions].map(x=>x.value),voiceCharacterIds:[...$('#clipVoiceCharacters').selectedOptions].map(x=>x.value)};if(!data.title)return;let c=p.clips.find(x=>x.id===editingClip);if(c)Object.assign(c,data);else p.clips.push({id:uid(),...data});save();$('#clipDialog').close();render();toast('Klip storyboard tersimpan.')};
$('#exportBtn').onclick=()=>{const p=project();if(!p)return toast('Tidak ada proyek aktif.');downloadText(`${p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-lpp-project.json`,JSON.stringify(p,null,2),'application/json')};
$('#backupBtn').onclick=()=>downloadText('lehan-ai-film-studio-workspace-backup.json',JSON.stringify({schemaVersion:2,exportedAt:new Date().toISOString(),activeProjectId:state.activeProjectId,projects:state.projects},null,2),'application/json');
$('#importBtn').onclick=()=>$('#importFile').click();
$('#importFile').onchange=async e=>{
 const file=e.target.files?.[0];if(!file)return;
 try{
  if(file.size>25*1024*1024)throw new Error('File melebihi batas 25 MB. Pecah backup atau kurangi ukuran gambar referensi.');
  const data=JSON.parse(await file.text());
  const sourceProjects=data&&Array.isArray(data.projects)?data.projects:[data];
  if(!sourceProjects.length)throw new Error('Backup tidak memiliki proyek.');
  const validProject=p=>p&&typeof p==='object'&&!Array.isArray(p)&&typeof p.name==='string'&&p.name.trim()&&Array.isArray(p.characters)&&Array.isArray(p.clips)&&p.characters.every(c=>c&&typeof c==='object'&&!Array.isArray(c))&&p.clips.every(c=>c&&typeof c==='object'&&!Array.isArray(c));
  if(!sourceProjects.every(validProject))throw new Error('Struktur JSON tidak valid. Setiap proyek harus memiliki nama, daftar karakter, dan daftar klip yang benar.');
  const candidate=structuredClone(state);
  const imported=sourceProjects.map(source=>{
   const p=structuredClone(source),oldCharacters=p.characters||[],idMap=new Map();
   p.id=uid();p.name=p.name.trim()+' (Impor)';
   p.workspaceType=p.workspaceType||(/putri tujuh/i.test(source.name)?'lpp':'creator');
   p.generationMode=p.generationMode||'hybrid';p.masterBible=p.masterBible||{};
   p.characters=oldCharacters.map(c=>{const copy={...c,id:uid()};if(c.id!=null)idMap.set(c.id,copy.id);return copy});
   p.clips=(p.clips||[]).map(c=>({...c,id:uid(),characterIds:(c.characterIds||[]).map(id=>idMap.get(id)).filter(Boolean),voiceCharacterIds:(c.voiceCharacterIds||[]).map(id=>idMap.get(id)).filter(Boolean)}));
   return p;
  });
  candidate.projects.push(...imported);candidate.activeProjectId=imported[imported.length-1].id;
  if(!save(candidate))throw new Error('Impor dibatalkan karena penyimpanan perangkat tidak cukup. Proyek lama tetap dipertahankan; jangan hapus data browser.');
  state=candidate;setView('dashboard');
  const imageCount=imported.reduce((n,p)=>n+p.characters.reduce((m,c)=>m+['referenceImage','referenceFront','referenceSide','referenceFullBody'].filter(k=>typeof c[k]==='string'&&c[k]).length,0),0);
  toast('Impor berhasil: '+imported.length+' proyek; '+imageCount+' referensi gambar ikut dipertahankan.');
 }catch(err){toast(err.message||'File JSON tidak valid.');}
 finally{e.target.value='';}
};
function downloadDataUrl(name,dataUrl){const a=document.createElement('a');a.href=dataUrl;a.download=name;document.body.appendChild(a);a.click();a.remove();toast('Referensi gambar disiapkan untuk diunduh.')}
function downloadText(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);toast('File disiapkan untuk diunduh.')}
render();
